const cfg = $('Config').first().json;
const f = $('Leave Form').first().json;
const clean = (v) => String(v ?? '').trim();
const toISO = (v) => {
  const s = clean(v).slice(0, 10);
  return /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(s) && !isNaN(Date.parse(s + 'T00:00:00Z')) ? s : '';
};
const rows = (name) => $(name).all().map((i) => i.json);
const hasFn = (o, k) => clean(o[k]) !== '';
const employeeId = clean(f['Employee ID']).toUpperCase();
const workEmail = clean(f['Work Email']).toLowerCase();
const leaveType = clean(f['Leave Type']);
const start = toISO(f['Start Date']);
const end = toISO(f['End Date']);
const portion = clean(f['Day Portion']) || 'Full Day';
const reason = clean(f['Reason']);
const columns = { 'Annual Leave': 'annual_leave', 'Sick Leave': 'sick_leave', 'Childcare Leave': 'childcare_leave' };
const emp = rows('Read Employees').find((e) => clean(e.employee_id).toUpperCase() === employeeId);
const sendTo = (real) => (cfg.test_mode ? cfg.test_email : real);
const base = {
  request_id: cfg.request_id, submitted_at: cfg.submitted_at, employee_id: employeeId, work_email: workEmail,
  employee_name: emp ? clean(emp.name) : '', manager_email: emp ? clean(emp.manager_email) : '',
  leave_type: leaveType, start_date: start, end_date: end, day_portion: portion, reason,
  subject_prefix: cfg.test_mode ? '[TEST] ' : '', to_employee: sendTo(emp ? clean(emp.work_email) : workEmail),
  to_manager: sendTo(emp ? clean(emp.manager_email) : ''), to_hr: sendTo(cfg.hr_email), days: 0,
};
const reject = (message, days = 0) => [{ json: { ...base, days, eligible: false, decision_reason: message } }];
if (!emp) return reject('We could not find that Employee ID. Please check it and apply again.');
if (clean(emp.work_email).toLowerCase() !== workEmail) return reject('Your Employee ID and work email do not match our records.');
const balanceColumn = columns[leaveType];
if (!balanceColumn) return reject('That leave type is not recognised. Please contact HR.');
if (!start || !end) return reject('The dates could not be read. Please apply again.');
if (end < start) return reject('The end date is before the start date.');
const halfDay = portion !== 'Full Day';
if (halfDay && start !== end) return reject('A half day must start and end on the same date.');
const holidays = new Set(rows('Read Holidays').map((h) => toISO(h.date)).filter(Boolean));
let days = 0;
let cursor = new Date(start + 'T00:00:00Z');
const last = new Date(end + 'T00:00:00Z');
while (cursor <= last) {
  const iso = cursor.toISOString().slice(0, 10);
  const weekday = cursor.getUTCDay();
  if (weekday !== 0 && weekday !== 6 && !holidays.has(iso)) days += 1;
  cursor = new Date(cursor.getTime() + 86400000);
}
if (halfDay && days > 0) days = 0.5;
if (days === 0) return reject('The dates chosen fall on weekends or public holidays, so there are no working days to apply for.');
const others = rows('Read Leave Requests').filter((r) => clean(r.employee_id).toUpperCase() === employeeId && clean(r.request_id) !== cfg.request_id);
const active = others.filter((r) => ['Pending', 'Approved'].includes(clean(r.status)));
const clash = active.find((r) => toISO(r.start_date) <= end && toISO(r.end_date) >= start);
if (clash) return reject('These dates overlap request ' + clean(clash.request_id) + ' (' + clean(clash.status) + ').', days);
const balance = Number(emp[balanceColumn]);
if (!hasFn(emp, balanceColumn) || isNaN(balance)) return reject('No ' + leaveType + ' balance is on record. Please contact HR.', days);
const pending = others.filter((r) => clean(r.status) === 'Pending' && clean(r.leave_type) === leaveType).reduce((sum, r) => sum + (Number(r.days) || 0), 0);
const available = balance - pending;
if (days > available) return reject('Insufficient ' + leaveType + ': you asked for ' + days + ' day(s) but only ' + available + ' are available (balance ' + balance + ', pending ' + pending + ').', days);
return [{ json: { ...base, days, eligible: true, decision_reason: '', balance_before: balance, available_after: available - days } }];

